import re
from fractions import Fraction

_NUM = r"(?:\d+(?:\.\d+)?|\.\d+)"

_UNIT_SECONDS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNIT_SECONDS[_n] = _secs

_COMPONENT_RE = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)")
_FULL_COMPONENTS_RE = re.compile(r"(?:" + _NUM + r"\s*[A-Za-z]+\s*)+")
_ISO_RE = re.compile(
    r"P"
    r"(?:(?P<W>" + _NUM + r")W)?"
    r"(?:(?P<D>" + _NUM + r")D)?"
    r"(?:T"
    r"(?:(?P<TH>" + _NUM + r")H)?"
    r"(?:(?P<TM>" + _NUM + r")M)?"
    r"(?:(?P<TS>" + _NUM + r")S)?"
    r")?",
    re.IGNORECASE,
)
_CLOCK_RE = re.compile(r"(\d+):(\d+)(?::(\d+))?")


def _round(total: Fraction) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(total + Fraction(1, 2))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare non-negative integer: seconds.
    if s.isdigit() and s.isascii():
        return int(s)

    # ISO 8601 duration.
    if s[0] in "Pp":
        m = _ISO_RE.fullmatch(s)
        if not m or s[-1] in "Pp" or s[-1] in "Tt":
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        groups = m.groupdict()
        if all(v is None for v in groups.values()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        if "T" in s.upper() and all(groups[k] is None for k in ("TH", "TM", "TS")):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        total = Fraction(0)
        for key, secs in (("W", 604800), ("D", 86400), ("TH", 3600), ("TM", 60), ("TS", 1)):
            if groups[key] is not None:
                total += Fraction(groups[key]) * secs
        return _round(total)

    # Clock notation: hh:mm:ss or mm:ss.
    if ":" in s:
        m = _CLOCK_RE.fullmatch(s)
        if not m:
            raise ValueError(f"invalid clock duration: {text!r}")
        fields = [f for f in m.groups() if f is not None]
        if len(fields) == 2:
            mins, secs = int(fields[0]), int(fields[1])
            hours = 0
        else:
            hours, mins, secs = int(fields[0]), int(fields[1]), int(fields[2])
        if mins >= 60 or secs >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return hours * 3600 + mins * 60 + secs

    # Unit components, optionally separated by spaces.
    if not _FULL_COMPONENTS_RE.fullmatch(s):
        raise ValueError(f"invalid duration: {text!r}")
    total = Fraction(0)
    pos = 0
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        value, unit = m.group(1), m.group(2).lower()
        if unit not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit {unit!r} in {text!r}")
        total += Fraction(value) * _UNIT_SECONDS[unit]
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    return _round(total)

